import 'package:flutter/material.dart';
import '../../domain/entities/business.dart';
class BusinessCard extends StatelessWidget { const BusinessCard({required this.business, required this.onTap, super.key}); final Business business; final VoidCallback onTap; @override Widget build(BuildContext context){ final q=business.queue; return Card(clipBehavior: Clip.antiAlias, child: InkWell(onTap:onTap, child: Padding(padding: const EdgeInsets.all(12), child: Row(crossAxisAlignment: CrossAxisAlignment.start, children:[Container(width:72,height:72,decoration:BoxDecoration(color:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(8)),clipBehavior:Clip.antiAlias,child: business.imageUrl==null?const Icon(Icons.storefront_outlined):Image.network(business.imageUrl!,fit:BoxFit.cover,errorBuilder:(_,_,_)=>const Icon(Icons.storefront_outlined))), const SizedBox(width:12), Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(business.name,style:Theme.of(context).textTheme.titleMedium,maxLines:1,overflow:TextOverflow.ellipsis)), const SizedBox(width:8), const Icon(Icons.star,size:16), const SizedBox(width:2), Text(business.rating?.toStringAsFixed(1)??'-')]), const SizedBox(height:4), Text(business.category.name,style:TextStyle(color:Theme.of(context).colorScheme.primary,fontWeight:FontWeight.w600)), const SizedBox(height:6), Text(business.address,maxLines:2,overflow:TextOverflow.ellipsis), const SizedBox(height:10), Wrap(spacing:8,runSpacing:8,children:[_Chip(icon:Icons.confirmation_number_outlined,label:q.currentNumber??'No queue'),_Chip(icon:Icons.groups_outlined,label:'${q.peopleWaiting} waiting'),_Chip(icon:Icons.schedule,label:'${q.estimatedWaitingTimeMinutes} min')])]))]))));}}
class _Chip extends StatelessWidget{ const _Chip({required this.icon,required this.label}); final IconData icon; final String label; @override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.symmetric(horizontal:8,vertical:6),decoration:BoxDecoration(color:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(8)),child:Row(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:16),const SizedBox(width:4),Text(label)]));}